INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Який запис повідомляє браузеру, що документ потрібно обробляти у стандартному режимі HTML?',NULL,'["<!doctype html>","<html>","<head>","<meta charset=\"UTF-8\">"]'::jsonb,'[0]'::jsonb,'Правильна відповідь: <!doctype html>. Варіант «<!doctype html>» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «<html>» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «<head>» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «<meta charset="UTF-8">» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='basics';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Який елемент є кореневим елементом HTML-документа?',NULL,'["<html>","<head>","<body>","<main>"]'::jsonb,'[0]'::jsonb,'Правильна відповідь: <html>. Варіант «<html>» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «<head>» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «<body>» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «<main>» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='basics';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Який елемент містить видимий вміст HTML-документа?',NULL,'["<body>","<head>","<html>","<title>"]'::jsonb,'[0]'::jsonb,'Правильна відповідь: <body>. Варіант «<body>» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «<head>» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «<html>» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «<title>» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='basics';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Який атрибут задає унікальний ідентифікатор елемента?',NULL,'["id","class","name","title"]'::jsonb,'[0]'::jsonb,'Правильна відповідь: id. Варіант «id» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «class» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «name» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «title» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='basics';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Який атрибут групує елементи за спільною назвою?',NULL,'["class","id","lang","title"]'::jsonb,'[0]'::jsonb,'Правильна відповідь: class. Варіант «class» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «id» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «lang» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «title» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='basics';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які два твердження про <!doctype html> правильні?',NULL,'["Оголошення <!doctype html> указує браузеру використовувати стандартний режим HTML.","Оголошення <!doctype html> записують перед кореневим елементом <html>.","Оголошення <!doctype html> задає кодування документа.","Оголошення <!doctype html> підключає зовнішню таблицю стилів.","Оголошення <!doctype html> визначає мову документа."]'::jsonb,'[0,1]'::jsonb,'Правильні відповіді: Оголошення <!doctype html> указує браузеру використовувати стандартний режим HTML.; Оголошення <!doctype html> записують перед кореневим елементом <html>.. Варіант «Оголошення <!doctype html> указує браузеру використовувати стандартний режим HTML.» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «Оголошення <!doctype html> записують перед кореневим елементом <html>.» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «Оголошення <!doctype html> задає кодування документа.» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Оголошення <!doctype html> підключає зовнішню таблицю стилів.» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Оголошення <!doctype html> визначає мову документа.» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='basics';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які два елементи безпосередньо розділяють HTML-документ на службову та видиму частини?',NULL,'["<head>","<body>","<main>","<title>","<header>"]'::jsonb,'[0,1]'::jsonb,'Правильні відповіді: <head>; <body>. Варіант «<head>» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «<body>» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «<main>» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «<title>» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «<header>» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='basics';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які два твердження про атрибут lang правильні?',NULL,'["Атрибут lang указує мову текстового вмісту елемента.","Атрибут lang на <html> задає основну мову документа.","Атрибут lang задає кодування символів документа.","Атрибут lang створює унікальний ідентифікатор.","Атрибут lang визначає напрямок письма."]'::jsonb,'[0,1]'::jsonb,'Правильні відповіді: Атрибут lang указує мову текстового вмісту елемента.; Атрибут lang на <html> задає основну мову документа.. Варіант «Атрибут lang указує мову текстового вмісту елемента.» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «Атрибут lang на <html> задає основну мову документа.» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «Атрибут lang задає кодування символів документа.» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Атрибут lang створює унікальний ідентифікатор.» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Атрибут lang визначає напрямок письма.» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='basics';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які два варіанти HTML-розмітки мають правильну вкладеність?',NULL,'["<p><strong>Текст</strong></p>","<ul><li>Пункт</li></ul>","<p><strong>Текст</p></strong>","<ul>Пункт<li></li></ul>","<head><body>Вміст</body></head>"]'::jsonb,'[0,1]'::jsonb,'Правильні відповіді: <p><strong>Текст</strong></p>; <ul><li>Пункт</li></ul>. Варіант «<p><strong>Текст</strong></p>» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «<ul><li>Пункт</li></ul>» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «<p><strong>Текст</p></strong>» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «<ul>Пункт<li></li></ul>» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «<head><body>Вміст</body></head>» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='basics';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які два твердження про void-елементи правильні?',NULL,'["Void-елемент <img> не має окремого закривального тегу.","Void-елемент <br> вставляє перенесення рядка.","Елемент <img> потрібно завершувати тегом </img>.","Елемент <br> може містити текстовий вміст.","Void-елементи потрібно записувати лише всередині <head>."]'::jsonb,'[0,1]'::jsonb,'Правильні відповіді: Void-елемент <img> не має окремого закривального тегу.; Void-елемент <br> вставляє перенесення рядка.. Варіант «Void-елемент <img> не має окремого закривального тегу.» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «Void-елемент <br> вставляє перенесення рядка.» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «Елемент <img> потрібно завершувати тегом </img>.» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Елемент <br> може містити текстовий вміст.» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Void-елементи потрібно записувати лише всередині <head>.» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='basics';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'hard','Які два твердження про <!doctype html> правильні?',NULL,'["Оголошення <!doctype html> розміщують перед елементом <html>.","Оголошення <!doctype html> допомагає браузеру вибрати стандартний режим відображення.","Оголошення <!doctype html> задає кодування UTF-8.","Оголошення <!doctype html> визначає мову документа.","Оголошення <!doctype html> підключає основну таблицю стилів.","Оголошення <!doctype html> створює елемент <body>."]'::jsonb,'[0,1]'::jsonb,'Правильні відповіді: Оголошення <!doctype html> розміщують перед елементом <html>.; Оголошення <!doctype html> допомагає браузеру вибрати стандартний режим відображення.. Варіант «Оголошення <!doctype html> розміщують перед елементом <html>.» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «Оголошення <!doctype html> допомагає браузеру вибрати стандартний режим відображення.» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «Оголошення <!doctype html> задає кодування UTF-8.» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Оголошення <!doctype html> визначає мову документа.» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Оголошення <!doctype html> підключає основну таблицю стилів.» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Оголошення <!doctype html> створює елемент <body>.» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='basics';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'hard','Які два твердження про елемент <html> правильні?',NULL,'["Елемент <html> є кореневим елементом HTML-документа.","Елементи <head> і <body> розміщують усередині <html>.","Елемент <html> містить лише видимий вміст сторінки.","Елемент <html> використовують замість <!doctype html>.","Елемент <html> може бути дочірнім елементом <body>.","Елемент <html> задає кодування документа без <meta>."]'::jsonb,'[0,1]'::jsonb,'Правильні відповіді: Елемент <html> є кореневим елементом HTML-документа.; Елементи <head> і <body> розміщують усередині <html>.. Варіант «Елемент <html> є кореневим елементом HTML-документа.» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «Елементи <head> і <body> розміщують усередині <html>.» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «Елемент <html> містить лише видимий вміст сторінки.» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Елемент <html> використовують замість <!doctype html>.» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Елемент <html> може бути дочірнім елементом <body>.» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Елемент <html> задає кодування документа без <meta>.» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='basics';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'hard','Які два твердження про елемент <body> правильні?',NULL,'["Елемент <body> містить видимий вміст HTML-документа.","HTML-документ має не більше одного елемента <body>.","Елемент <body> призначений лише для метаданих документа.","Елемент <body> потрібно розміщувати всередині <head>.","Елемент <body> замінює кореневий елемент <html>.","Елемент <body> не може містити елементи <p>."]'::jsonb,'[0,1]'::jsonb,'Правильні відповіді: Елемент <body> містить видимий вміст HTML-документа.; HTML-документ має не більше одного елемента <body>.. Варіант «Елемент <body> містить видимий вміст HTML-документа.» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «HTML-документ має не більше одного елемента <body>.» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «Елемент <body> призначений лише для метаданих документа.» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Елемент <body> потрібно розміщувати всередині <head>.» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Елемент <body> замінює кореневий елемент <html>.» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Елемент <body> не може містити елементи <p>.» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='basics';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'hard','Які два твердження про атрибут id правильні?',NULL,'["Значення id має ідентифікувати один елемент у документі.","Значення id можна використовувати як ціль фрагментного URL.","Атрибут id групує довільну кількість елементів під одним значенням.","Атрибут id задає мову текстового вмісту.","Значення id потрібно дублювати для пов’язаних елементів.","Атрибут id можна використовувати лише з елементом <div>."]'::jsonb,'[0,1]'::jsonb,'Правильні відповіді: Значення id має ідентифікувати один елемент у документі.; Значення id можна використовувати як ціль фрагментного URL.. Варіант «Значення id має ідентифікувати один елемент у документі.» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «Значення id можна використовувати як ціль фрагментного URL.» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «Атрибут id групує довільну кількість елементів під одним значенням.» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Атрибут id задає мову текстового вмісту.» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Значення id потрібно дублювати для пов’язаних елементів.» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Атрибут id можна використовувати лише з елементом <div>.» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='basics';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'hard','Які два твердження про атрибут class правильні?',NULL,'["Атрибут class групує елементи за спільними назвами класів.","Один елемент може мати кілька назв класів.","Значення class має бути унікальним у всьому документі.","Атрибут class задає адресу переходу для <a>.","Атрибут class визначає основну мову документа.","Атрибут class можна використовувати лише з елементом <div>."]'::jsonb,'[0,1]'::jsonb,'Правильні відповіді: Атрибут class групує елементи за спільними назвами класів.; Один елемент може мати кілька назв класів.. Варіант «Атрибут class групує елементи за спільними назвами класів.» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «Один елемент може мати кілька назв класів.» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «Значення class має бути унікальним у всьому документі.» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Атрибут class задає адресу переходу для <a>.» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Атрибут class визначає основну мову документа.» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Атрибут class можна використовувати лише з елементом <div>.» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='basics';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Який елемент позначає окремий абзац тексту?',NULL,'["<p>","<h1>","<span>","<blockquote>"]'::jsonb,'[0]'::jsonb,'Правильна відповідь: <p>. Варіант «<p>» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «<h1>» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «<span>» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «<blockquote>» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='text';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Який елемент позначає заголовок найвищого рівня?',NULL,'["<h1>","<h2>","<p>","<title>"]'::jsonb,'[0]'::jsonb,'Правильна відповідь: <h1>. Варіант «<h1>» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «<h2>» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «<p>» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «<title>» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='text';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Який атрибут елемента <a> задає адресу переходу?',NULL,'["href","target","rel","download"]'::jsonb,'[0]'::jsonb,'Правильна відповідь: href. Варіант «href» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «target» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «rel» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «download» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='text';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Який елемент позначає текст як важливий?',NULL,'["<strong>","<b>","<em>","<mark>"]'::jsonb,'[0]'::jsonb,'Правильна відповідь: <strong>. Варіант «<strong>» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «<b>» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «<em>» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «<mark>» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='text';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Який елемент позначає розгорнуту цитату?',NULL,'["<blockquote>","<q>","<cite>","<p>"]'::jsonb,'[0]'::jsonb,'Правильна відповідь: <blockquote>. Варіант «<blockquote>» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «<q>» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «<cite>» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «<p>» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='text';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які два елементи позначають заголовок і окремий абзац тексту?',NULL,'["<h1>–<h6>","<p>","<strong>","<br>","<a>"]'::jsonb,'[0,1]'::jsonb,'Правильні відповіді: <h1>–<h6>; <p>. Варіант «<h1>–<h6>» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «<p>» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «<strong>» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «<br>» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «<a>» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='text';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які два твердження правильно описують різницю між <strong> і <b>?',NULL,'["Елемент <strong> позначає важливий текст.","Елемент <b> привертає увагу без семантики важливості.","Елемент <b> позначає текст як важливіший за <strong>.","Елемент <strong> використовують лише для декоративного жирного накреслення.","Елементи <strong> і <b> мають однакове семантичне значення."]'::jsonb,'[0,1]'::jsonb,'Правильні відповіді: Елемент <strong> позначає важливий текст.; Елемент <b> привертає увагу без семантики важливості.. Варіант «Елемент <strong> позначає важливий текст.» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «Елемент <b> привертає увагу без семантики важливості.» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «Елемент <b> позначає текст як важливіший за <strong>.» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Елемент <strong> використовують лише для декоративного жирного накреслення.» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Елементи <strong> і <b> мають однакове семантичне значення.» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='text';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які два твердження правильно описують різницю між <em> і <i>?',NULL,'["Елемент <em> позначає логічний наголос.","Елемент <i> виділяє текст без семантики наголосу.","Елемент <i> позначає сильніший наголос, ніж <em>.","Елемент <em> використовують лише для декоративного курсиву.","Елементи <em> і <i> мають однакове семантичне значення."]'::jsonb,'[0,1]'::jsonb,'Правильні відповіді: Елемент <em> позначає логічний наголос.; Елемент <i> виділяє текст без семантики наголосу.. Варіант «Елемент <em> позначає логічний наголос.» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «Елемент <i> виділяє текст без семантики наголосу.» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «Елемент <i> позначає сильніший наголос, ніж <em>.» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Елемент <em> використовують лише для декоративного курсиву.» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Елементи <em> і <i> мають однакове семантичне значення.» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='text';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які два твердження про посилання на фрагмент документа правильні?',NULL,'["Атрибут href у <a> задає адресу переходу.","Значення href=\"#contacts\" веде до елемента з id=\"contacts\".","Атрибут target задає id цільового елемента.","Значення href=\"#contacts\" шукає елемент із class=\"contacts\".","Фрагментний URL працює лише для елементів <img>."]'::jsonb,'[0,1]'::jsonb,'Правильні відповіді: Атрибут href у <a> задає адресу переходу.; Значення href="#contacts" веде до елемента з id="contacts".. Варіант «Атрибут href у <a> задає адресу переходу.» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «Значення href="#contacts" веде до елемента з id="contacts".» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «Атрибут target задає id цільового елемента.» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Значення href="#contacts" шукає елемент із class="contacts".» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Фрагментний URL працює лише для елементів <img>.» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='text';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які два твердження про <code> і <blockquote> правильні?',NULL,'["Елемент <code> позначає фрагмент програмного коду.","Елемент <blockquote> позначає розгорнуту цитату.","Елемент <code> виконує JavaScript під час завантаження сторінки.","Елемент <blockquote> позначає коротку цитату всередині рядка.","Елемент <code> зберігає всі пробіли та перенесення без <pre>."]'::jsonb,'[0,1]'::jsonb,'Правильні відповіді: Елемент <code> позначає фрагмент програмного коду.; Елемент <blockquote> позначає розгорнуту цитату.. Варіант «Елемент <code> позначає фрагмент програмного коду.» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «Елемент <blockquote> позначає розгорнуту цитату.» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «Елемент <code> виконує JavaScript під час завантаження сторінки.» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Елемент <blockquote> позначає коротку цитату всередині рядка.» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Елемент <code> зберігає всі пробіли та перенесення без <pre>.» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='text';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'hard','Які два твердження про елемент <p> правильні?',NULL,'["Елемент <p> позначає окремий абзац тексту.","Початковий тег нового <p> завершує попередній відкритий абзац.","Елемент <p> позначає заголовок найвищого рівня.","Елемент <p> потрібно розміщувати всередині <head>.","Елемент <p> може містити інший елемент <p>.","Елемент <p> створює посилання без елемента <a>."]'::jsonb,'[0,1]'::jsonb,'Правильні відповіді: Елемент <p> позначає окремий абзац тексту.; Початковий тег нового <p> завершує попередній відкритий абзац.. Варіант «Елемент <p> позначає окремий абзац тексту.» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «Початковий тег нового <p> завершує попередній відкритий абзац.» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «Елемент <p> позначає заголовок найвищого рівня.» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Елемент <p> потрібно розміщувати всередині <head>.» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Елемент <p> може містити інший елемент <p>.» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Елемент <p> створює посилання без елемента <a>.» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='text';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'hard','Які два твердження про елементи <h1>–<h6> правильні?',NULL,'["Елемент <h1> має найвищий рівень заголовка.","Елементи <h1>–<h6> передають ієрархію заголовків.","Елемент <h6> має вищий рівень за <h1>.","Елементи <h1>–<h6> призначені лише для зміни розміру шрифту.","Елементи <h1>–<h6> потрібно розміщувати всередині <head>.","Усі елементи <h1>–<h6> мають однаковий рівень."]'::jsonb,'[0,1]'::jsonb,'Правильні відповіді: Елемент <h1> має найвищий рівень заголовка.; Елементи <h1>–<h6> передають ієрархію заголовків.. Варіант «Елемент <h1> має найвищий рівень заголовка.» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «Елементи <h1>–<h6> передають ієрархію заголовків.» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «Елемент <h6> має вищий рівень за <h1>.» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Елементи <h1>–<h6> призначені лише для зміни розміру шрифту.» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Елементи <h1>–<h6> потрібно розміщувати всередині <head>.» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Усі елементи <h1>–<h6> мають однаковий рівень.» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='text';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'hard','Які два твердження правильно описують <strong> і <b>?',NULL,'["Елемент <strong> позначає важливість тексту.","Елемент <b> привертає увагу без додаткової семантики важливості.","Елемент <b> передає більшу важливість, ніж <strong>.","Елемент <strong> призначений лише для декоративного жирного накреслення.","Елементи <strong> і <b> мають однакове семантичне значення.","Елемент <b> позначає логічний наголос замість <em>."]'::jsonb,'[0,1]'::jsonb,'Правильні відповіді: Елемент <strong> позначає важливість тексту.; Елемент <b> привертає увагу без додаткової семантики важливості.. Варіант «Елемент <strong> позначає важливість тексту.» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «Елемент <b> привертає увагу без додаткової семантики важливості.» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «Елемент <b> передає більшу важливість, ніж <strong>.» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Елемент <strong> призначений лише для декоративного жирного накреслення.» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Елементи <strong> і <b> мають однакове семантичне значення.» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Елемент <b> позначає логічний наголос замість <em>.» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='text';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'hard','Які два твердження правильно описують <em> і <i>?',NULL,'["Елемент <em> позначає логічний наголос.","Елемент <i> виділяє текст без семантики наголосу.","Елемент <i> передає сильніший наголос, ніж <em>.","Елемент <em> призначений лише для декоративного курсиву.","Елементи <em> і <i> мають однакове семантичне значення.","Елемент <i> позначає важливість замість <strong>."]'::jsonb,'[0,1]'::jsonb,'Правильні відповіді: Елемент <em> позначає логічний наголос.; Елемент <i> виділяє текст без семантики наголосу.. Варіант «Елемент <em> позначає логічний наголос.» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «Елемент <i> виділяє текст без семантики наголосу.» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «Елемент <i> передає сильніший наголос, ніж <em>.» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Елемент <em> призначений лише для декоративного курсиву.» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Елементи <em> і <i> мають однакове семантичне значення.» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Елемент <i> позначає важливість замість <strong>.» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='text';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'hard','Які два твердження про елементи <code> і <pre> правильні?',NULL,'["Елемент <code> позначає фрагмент програмного коду.","Елемент <pre> зберігає пробіли та перенесення рядків у тексті.","Елемент <code> виконує JavaScript під час завантаження сторінки.","Елемент <pre> перевіряє синтаксис вкладеного коду.","Елемент <code> зберігає всі пробіли без використання <pre>.","Елемент <pre> підключає зовнішній файл із програмним кодом."]'::jsonb,'[0,1]'::jsonb,'Правильні відповіді: Елемент <code> позначає фрагмент програмного коду.; Елемент <pre> зберігає пробіли та перенесення рядків у тексті.. Варіант «Елемент <code> позначає фрагмент програмного коду.» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «Елемент <pre> зберігає пробіли та перенесення рядків у тексті.» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «Елемент <code> виконує JavaScript під час завантаження сторінки.» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Елемент <pre> перевіряє синтаксис вкладеного коду.» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Елемент <code> зберігає всі пробіли без використання <pre>.» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Елемент <pre> підключає зовнішній файл із програмним кодом.» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='text';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Який елемент створює невпорядкований список?',NULL,'["<ul>","<ol>","<li>","<dl>"]'::jsonb,'[0]'::jsonb,'Правильна відповідь: <ul>. Варіант «<ul>» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «<ol>» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «<li>» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «<dl>» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='lists-tables';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Який елемент створює впорядкований список?',NULL,'["<ol>","<ul>","<li>","<dl>"]'::jsonb,'[0]'::jsonb,'Правильна відповідь: <ol>. Варіант «<ol>» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «<ul>» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «<li>» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «<dl>» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='lists-tables';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Який елемент позначає пункт у списках <ul> та <ol>?',NULL,'["<li>","<dt>","<dd>","<tr>"]'::jsonb,'[0]'::jsonb,'Правильна відповідь: <li>. Варіант «<li>» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «<dt>» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «<dd>» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «<tr>» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='lists-tables';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Який елемент позначає рядок таблиці?',NULL,'["<tr>","<td>","<th>","<table>"]'::jsonb,'[0]'::jsonb,'Правильна відповідь: <tr>. Варіант «<tr>» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «<td>» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «<th>» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «<table>» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='lists-tables';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Який елемент позначає заголовкову комірку таблиці?',NULL,'["<th>","<td>","<tr>","<caption>"]'::jsonb,'[0]'::jsonb,'Правильна відповідь: <th>. Варіант «<th>» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «<td>» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «<tr>» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «<caption>» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='lists-tables';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які два твердження про елемент <ul> правильні?',NULL,'["Елемент <ul> створює невпорядкований список.","Окремі пункти всередині <ul> позначають елементами <li>.","Елемент <ul> нумерує пункти списку за порядком.","Елемент <ul> може містити пункти без елементів <li>.","Елемент <ul> використовують для списку термінів і визначень."]'::jsonb,'[0,1]'::jsonb,'Правильні відповіді: Елемент <ul> створює невпорядкований список.; Окремі пункти всередині <ul> позначають елементами <li>.. Варіант «Елемент <ul> створює невпорядкований список.» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «Окремі пункти всередині <ul> позначають елементами <li>.» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «Елемент <ul> нумерує пункти списку за порядком.» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Елемент <ul> може містити пункти без елементів <li>.» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Елемент <ul> використовують для списку термінів і визначень.» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='lists-tables';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які два твердження про <ol> і <li> правильні?',NULL,'["Елемент <ol> створює впорядкований список.","Елемент <li> позначає окремий пункт списку.","Елемент <ol> створює невпорядкований список.","Елемент <li> задає початковий номер усього списку.","Елемент <ol> може містити пункти без <li>."]'::jsonb,'[0,1]'::jsonb,'Правильні відповіді: Елемент <ol> створює впорядкований список.; Елемент <li> позначає окремий пункт списку.. Варіант «Елемент <ol> створює впорядкований список.» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «Елемент <li> позначає окремий пункт списку.» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «Елемент <ol> створює невпорядкований список.» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Елемент <li> задає початковий номер усього списку.» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Елемент <ol> може містити пункти без <li>.» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='lists-tables';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які два елементи використовують для рядка таблиці та звичайної комірки?',NULL,'["<tr>","<td>","<table>","<th>","<caption>"]'::jsonb,'[0,1]'::jsonb,'Правильні відповіді: <tr>; <td>. Варіант «<tr>» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «<td>» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «<table>» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «<th>» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «<caption>» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='lists-tables';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які два атрибути об’єднують комірку з кількома стовпцями або рядками?',NULL,'["colspan","rowspan","scope","headers","span"]'::jsonb,'[0,1]'::jsonb,'Правильні відповіді: colspan; rowspan. Варіант «colspan» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «rowspan» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «scope» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «headers» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «span» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='lists-tables';
