INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Який атрибут позначає поле як обов’язкове?',NULL,'["required","readonly","disabled","multiple"]'::jsonb,'[0]'::jsonb,'Правильна відповідь: required. Варіант «required» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «readonly» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «disabled» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «multiple» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='forms';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Який елемент створює багаторядкове текстове поле?',NULL,'["<textarea>","<input>","<select>","<output>"]'::jsonb,'[0]'::jsonb,'Правильна відповідь: <textarea>. Варіант «<textarea>» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «<input>» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «<select>» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «<output>» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='forms';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які два атрибути <form> задають адресу та HTTP-метод надсилання?',NULL,'["action","method","enctype","target","autocomplete"]'::jsonb,'[0,1]'::jsonb,'Правильні відповіді: action; method. Варіант «action» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «method» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «enctype» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «target» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «autocomplete» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='forms';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які два твердження про зв’язок <label> із полем правильні?',NULL,'["Значення for у <label> має збігатися зі значенням id поля.","Натискання пов’язаного <label> передає фокус полю.","Атрибут for задає адресу обробника форми.","Атрибут id поля визначає HTTP-метод надсилання.","Елемент <label> передає значення поля на сервер."]'::jsonb,'[0,1]'::jsonb,'Правильні відповіді: Значення for у <label> має збігатися зі значенням id поля.; Натискання пов’язаного <label> передає фокус полю.. Варіант «Значення for у <label> має збігатися зі значенням id поля.» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «Натискання пов’язаного <label> передає фокус полю.» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «Атрибут for задає адресу обробника форми.» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Атрибут id поля визначає HTTP-метод надсилання.» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Елемент <label> передає значення поля на сервер.» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='forms';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які два значення type відповідають полям електронної пошти та пароля?',NULL,'["email","password","text","search","tel"]'::jsonb,'[0,1]'::jsonb,'Правильні відповіді: email; password. Варіант «email» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «password» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «text» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «search» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «tel» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='forms';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які два атрибути задають обов’язковість і шаблон допустимого значення поля?',NULL,'["required","pattern","placeholder","readonly","autocomplete"]'::jsonb,'[0,1]'::jsonb,'Правильні відповіді: required; pattern. Варіант «required» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «pattern» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «placeholder» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «readonly» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «autocomplete» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='forms';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які два твердження правильно описують radio та checkbox?',NULL,'["Radio-кнопки з однаковим name утворюють групу одного вибору.","Checkbox дозволяє незалежно вибирати кілька значень.","Radio-кнопки з однаковим name дозволяють вибрати всі значення.","Checkbox з однаковим name утворюють групу лише одного вибору.","Атрибут checked заборонено використовувати з radio та checkbox."]'::jsonb,'[0,1]'::jsonb,'Правильні відповіді: Radio-кнопки з однаковим name утворюють групу одного вибору.; Checkbox дозволяє незалежно вибирати кілька значень.. Варіант «Radio-кнопки з однаковим name утворюють групу одного вибору.» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «Checkbox дозволяє незалежно вибирати кілька значень.» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «Radio-кнопки з однаковим name дозволяють вибрати всі значення.» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Checkbox з однаковим name утворюють групу лише одного вибору.» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Атрибут checked заборонено використовувати з radio та checkbox.» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='forms';
