INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Який елемент позначає основний вміст документа?',NULL,'["<main>","<nav>","<aside>","<footer>"]'::jsonb,'[0]'::jsonb,'Правильна відповідь: <main>. Варіант «<main>» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «<nav>» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «<aside>» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «<footer>» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='semantic';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Який елемент позначає область навігаційних посилань?',NULL,'["<nav>","<main>","<aside>","<header>"]'::jsonb,'[0]'::jsonb,'Правильна відповідь: <nav>. Варіант «<nav>» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «<main>» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «<aside>» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «<header>» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='semantic';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Який елемент позначає самостійну завершену композицію?',NULL,'["<article>","<section>","<div>","<aside>"]'::jsonb,'[0]'::jsonb,'Правильна відповідь: <article>. Варіант «<article>» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «<section>» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «<div>» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «<aside>» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='semantic';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Який елемент позначає тематичний розділ документа?',NULL,'["<section>","<article>","<nav>","<footer>"]'::jsonb,'[0]'::jsonb,'Правильна відповідь: <section>. Варіант «<section>» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «<article>» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «<nav>» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «<footer>» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='semantic';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Який елемент позначає додатковий вміст, опосередковано пов’язаний з основним?',NULL,'["<aside>","<main>","<article>","<nav>"]'::jsonb,'[0]'::jsonb,'Правильна відповідь: <aside>. Варіант «<aside>» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «<main>» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «<article>» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «<nav>» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='semantic';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які два елементи позначають основний вміст і область навігації?',NULL,'["<main>","<nav>","<article>","<aside>","<footer>"]'::jsonb,'[0,1]'::jsonb,'Правильні відповіді: <main>; <nav>. Варіант «<main>» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «<nav>» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «<article>» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «<aside>» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «<footer>» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='semantic';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які два твердження правильно описують <article> і <section>?',NULL,'["Елемент <article> підходить для самостійного матеріалу.","Елемент <section> групує тематично пов’язаний вміст.","Елемент <article> використовують лише як контейнер для стилів.","Елемент <section> не може мати заголовка.","Елементи <article> і <section> не мають семантичного значення."]'::jsonb,'[0,1]'::jsonb,'Правильні відповіді: Елемент <article> підходить для самостійного матеріалу.; Елемент <section> групує тематично пов’язаний вміст.. Варіант «Елемент <article> підходить для самостійного матеріалу.» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «Елемент <section> групує тематично пов’язаний вміст.» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «Елемент <article> використовують лише як контейнер для стилів.» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Елемент <section> не може мати заголовка.» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Елементи <article> і <section> не мають семантичного значення.» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='semantic';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які два твердження про семантичні елементи правильні?',NULL,'["Елемент <section> передає призначення тематичного розділу.","Елемент <article> позначає самостійну композицію.","Елемент <div> має вбудовану роль <article>.","Елемент <div> позначає основний вміст документа.","Елемент <section> використовують лише після підключення CSS."]'::jsonb,'[0,1]'::jsonb,'Правильні відповіді: Елемент <section> передає призначення тематичного розділу.; Елемент <article> позначає самостійну композицію.. Варіант «Елемент <section> передає призначення тематичного розділу.» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «Елемент <article> позначає самостійну композицію.» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «Елемент <div> має вбудовану роль <article>.» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Елемент <div> позначає основний вміст документа.» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Елемент <section> використовують лише після підключення CSS.» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='semantic';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які два твердження про <header> і <footer> правильні?',NULL,'["Елемент <header> містить вступний вміст або навігаційні засоби секції.","Елемент <footer> містить завершальну інформацію для секції або сторінки.","Елемент <header> є синонімом <head>.","Елемент <footer> дозволено використовувати лише один раз у документі.","Елемент <footer> має бути прямим дочірнім елементом <html>."]'::jsonb,'[0,1]'::jsonb,'Правильні відповіді: Елемент <header> містить вступний вміст або навігаційні засоби секції.; Елемент <footer> містить завершальну інформацію для секції або сторінки.. Варіант «Елемент <header> містить вступний вміст або навігаційні засоби секції.» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «Елемент <footer> містить завершальну інформацію для секції або сторінки.» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «Елемент <header> є синонімом <head>.» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Елемент <footer> дозволено використовувати лише один раз у документі.» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Елемент <footer> має бути прямим дочірнім елементом <html>.» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='semantic';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які два твердження про рівні заголовків правильні?',NULL,'["Елемент <h1> має найвищий рівень заголовка.","Елементи <h2>–<h6> позначають заголовки нижчих рівнів.","Елемент <h6> має вищий рівень за <h1>.","Рівень заголовка визначає лише розмір шрифту.","Елемент <h2> потрібно розміщувати лише після двох елементів <h1>."]'::jsonb,'[0,1]'::jsonb,'Правильні відповіді: Елемент <h1> має найвищий рівень заголовка.; Елементи <h2>–<h6> позначають заголовки нижчих рівнів.. Варіант «Елемент <h1> має найвищий рівень заголовка.» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «Елементи <h2>–<h6> позначають заголовки нижчих рівнів.» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «Елемент <h6> має вищий рівень за <h1>.» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Рівень заголовка визначає лише розмір шрифту.» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Елемент <h2> потрібно розміщувати лише після двох елементів <h1>.» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='semantic';
