INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Який елемент вбудовує зображення у сторінку?',NULL,'["<img>","<picture>","<source>","<figure>"]'::jsonb,'[0]'::jsonb,'Правильна відповідь: <img>. Варіант «<img>» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «<picture>» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «<source>» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «<figure>» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='media';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Який атрибут <img> містить текстову альтернативу зображенню?',NULL,'["alt","src","title","width"]'::jsonb,'[0]'::jsonb,'Правильна відповідь: alt. Варіант «alt» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «src» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «title» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «width» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='media';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Який елемент вбудовує відео у сторінку?',NULL,'["<video>","<audio>","<source>","<track>"]'::jsonb,'[0]'::jsonb,'Правильна відповідь: <video>. Варіант «<video>» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «<audio>» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «<source>» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «<track>» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='media';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Який елемент задає альтернативний медіаресурс для <video> або <audio>?',NULL,'["<source>","<track>","<picture>","<embed>"]'::jsonb,'[0]'::jsonb,'Правильна відповідь: <source>. Варіант «<source>» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «<track>» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «<picture>» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «<embed>» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='media';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Який елемент підключає субтитри у форматі WebVTT?',NULL,'["<track>","<source>","<caption>","<text>"]'::jsonb,'[0]'::jsonb,'Правильна відповідь: <track>. Варіант «<track>» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «<source>» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «<caption>» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «<text>» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='media';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які два атрибути <img> задають адресу зображення та текстову альтернативу?',NULL,'["src","alt","width","loading","decoding"]'::jsonb,'[0,1]'::jsonb,'Правильні відповіді: src; alt. Варіант «src» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «alt» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «width» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «loading» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «decoding» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='media';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які два твердження про <video> правильні?',NULL,'["Атрибут controls додає користувацькі елементи керування відео.","Елемент <source> задає альтернативний відеоресурс.","Атрибут controls задає адресу відеофайлу.","Елемент <source> підключає файл субтитрів.","Елемент <video> може містити лише один <source>."]'::jsonb,'[0,1]'::jsonb,'Правильні відповіді: Атрибут controls додає користувацькі елементи керування відео.; Елемент <source> задає альтернативний відеоресурс.. Варіант «Атрибут controls додає користувацькі елементи керування відео.» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «Елемент <source> задає альтернативний відеоресурс.» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «Атрибут controls задає адресу відеофайлу.» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Елемент <source> підключає файл субтитрів.» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Елемент <video> може містити лише один <source>.» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='media';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які два твердження про доступну назву <iframe> правильні?',NULL,'["Атрибут src задає адресу вбудованого документа.","Атрибут title описує призначення вбудованого документа.","Атрибут title задає ширину <iframe>.","Атрибут src створює текстову альтернативу для <iframe>.","Атрибут title замінює вміст вбудованого документа."]'::jsonb,'[0,1]'::jsonb,'Правильні відповіді: Атрибут src задає адресу вбудованого документа.; Атрибут title описує призначення вбудованого документа.. Варіант «Атрибут src задає адресу вбудованого документа.» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «Атрибут title описує призначення вбудованого документа.» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «Атрибут title задає ширину <iframe>.» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Атрибут src створює текстову альтернативу для <iframe>.» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Атрибут title замінює вміст вбудованого документа.» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='media';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які два твердження про субтитри у <video> правильні?',NULL,'["Елемент <track> підключають як дочірній елемент <video>.","Атрибут src у <track> задає адресу файлу WebVTT.","Елемент <track> задає основний відеофайл.","Атрибут kind=\"subtitles\" змінює звукову доріжку відео.","Файл WebVTT потрібно підключати через <source>."]'::jsonb,'[0,1]'::jsonb,'Правильні відповіді: Елемент <track> підключають як дочірній елемент <video>.; Атрибут src у <track> задає адресу файлу WebVTT.. Варіант «Елемент <track> підключають як дочірній елемент <video>.» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «Атрибут src у <track> задає адресу файлу WebVTT.» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «Елемент <track> задає основний відеофайл.» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Атрибут kind="subtitles" змінює звукову доріжку відео.» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Файл WebVTT потрібно підключати через <source>.» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='media';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які два твердження про адаптивні зображення у <picture> правильні?',NULL,'["Елемент <source> може містити умову media.","Елемент <img> усередині <picture> є запасним варіантом.","Елемент <picture> призначений для відтворення аудіо.","Елемент <source> створює текстову альтернативу замість alt.","Елемент <img> заборонено вкладати у <picture>."]'::jsonb,'[0,1]'::jsonb,'Правильні відповіді: Елемент <source> може містити умову media.; Елемент <img> усередині <picture> є запасним варіантом.. Варіант «Елемент <source> може містити умову media.» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «Елемент <img> усередині <picture> є запасним варіантом.» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «Елемент <picture> призначений для відтворення аудіо.» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Елемент <source> створює текстову альтернативу замість alt.» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Елемент <img> заборонено вкладати у <picture>.» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='media';
