INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Який елемент містить метадані HTML-документа?',NULL,'["<head>","<header>","<meta>","<body>"]'::jsonb,'[0]'::jsonb,'Правильна відповідь: <head>. Варіант «<head>» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «<header>» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «<meta>» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «<body>» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='head';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Який елемент задає назву вкладки браузера?',NULL,'["<title>","<h1>","<header>","<meta>"]'::jsonb,'[0]'::jsonb,'Правильна відповідь: <title>. Варіант «<title>» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «<h1>» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «<header>» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «<meta>» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='head';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Який атрибут <meta> оголошує кодування документа?',NULL,'["charset","content","name","lang"]'::jsonb,'[0]'::jsonb,'Правильна відповідь: charset. Варіант «charset» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «content» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «name» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «lang» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='head';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Яке значення rel використовують для підключення таблиці стилів через <link>?',NULL,'["stylesheet","icon","canonical","preload"]'::jsonb,'[0]'::jsonb,'Правильна відповідь: stylesheet. Варіант «stylesheet» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «icon» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «canonical» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «preload» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='head';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Яке значення name використовують у <meta> для короткого опису сторінки?',NULL,'["description","viewport","author","robots"]'::jsonb,'[0]'::jsonb,'Правильна відповідь: description. Варіант «description» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «viewport» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «author» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «robots» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='head';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які два елементи задають назву документа та його кодування?',NULL,'["<title>","<meta charset=\"UTF-8\">","<link>","<style>","<script>"]'::jsonb,'[0,1]'::jsonb,'Правильні відповіді: <title>; <meta charset="UTF-8">. Варіант «<title>» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «<meta charset="UTF-8">» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «<link>» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «<style>» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «<script>» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='head';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які два твердження про charset і viewport правильні?',NULL,'["Атрибут charset задає кодування документа.","Метатег viewport налаштовує область перегляду на мобільному пристрої.","Атрибут charset задає основну мову документа.","Метатег viewport задає назву вкладки браузера.","Атрибут charset визначає ширину області перегляду."]'::jsonb,'[0,1]'::jsonb,'Правильні відповіді: Атрибут charset задає кодування документа.; Метатег viewport налаштовує область перегляду на мобільному пристрої.. Варіант «Атрибут charset задає кодування документа.» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «Метатег viewport налаштовує область перегляду на мобільному пристрої.» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «Атрибут charset задає основну мову документа.» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Метатег viewport задає назву вкладки браузера.» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Атрибут charset визначає ширину області перегляду.» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='head';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які два твердження про підключення favicon правильні?',NULL,'["Елемент <link> із rel=\"icon\" описує піктограму сторінки.","Атрибут href у <link> задає адресу файлу піктограми.","Елемент <img> у <body> стає favicon сторінки.","Значення rel=\"stylesheet\" позначає favicon.","Елемент <title> задає адресу файлу favicon."]'::jsonb,'[0,1]'::jsonb,'Правильні відповіді: Елемент <link> із rel="icon" описує піктограму сторінки.; Атрибут href у <link> задає адресу файлу піктограми.. Варіант «Елемент <link> із rel="icon" описує піктограму сторінки.» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «Атрибут href у <link> задає адресу файлу піктограми.» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «Елемент <img> у <body> стає favicon сторінки.» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Значення rel="stylesheet" позначає favicon.» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Елемент <title> задає адресу файлу favicon.» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='head';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які два твердження про Open Graph-метадані правильні?',NULL,'["Метатег із property=\"og:title\" задає заголовок публікації.","Метатег із property=\"og:image\" задає зображення публікації.","Метатег із property=\"og:title\" змінює текст <h1>.","Метатег із property=\"og:image\" підключає таблицю стилів.","Open Graph-метатеги потрібно розміщувати всередині <body>."]'::jsonb,'[0,1]'::jsonb,'Правильні відповіді: Метатег із property="og:title" задає заголовок публікації.; Метатег із property="og:image" задає зображення публікації.. Варіант «Метатег із property="og:title" задає заголовок публікації.» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «Метатег із property="og:image" задає зображення публікації.» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «Метатег із property="og:title" змінює текст <h1>.» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Метатег із property="og:image" підключає таблицю стилів.» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Open Graph-метатеги потрібно розміщувати всередині <body>.» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='head';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які два твердження про <title> правильні?',NULL,'["Елемент <title> розміщують усередині <head>.","Елемент <title> задає назву документа у вкладці браузера.","Елемент <title> відображає основний заголовок у <body>.","Елемент <title> задає кодування документа.","Елемент <title> є синонімом <header>."]'::jsonb,'[0,1]'::jsonb,'Правильні відповіді: Елемент <title> розміщують усередині <head>.; Елемент <title> задає назву документа у вкладці браузера.. Варіант «Елемент <title> розміщують усередині <head>.» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «Елемент <title> задає назву документа у вкладці браузера.» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «Елемент <title> відображає основний заголовок у <body>.» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Елемент <title> задає кодування документа.» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Елемент <title> є синонімом <header>.» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='head';
