INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Який елемент створює видимий підпис для поля форми?',NULL,'["<label>","<legend>","<caption>","<output>"]'::jsonb,'[0]'::jsonb,'Правильна відповідь: <label>. Варіант «<label>» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «<legend>» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «<caption>» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «<output>» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='accessibility';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Який елемент має вбудовану клавіатурну активацію для виконання дії?',NULL,'["<button>","<div>","<span>","<section>"]'::jsonb,'[0]'::jsonb,'Правильна відповідь: <button>. Варіант «<button>» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «<div>» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «<span>» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «<section>» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='accessibility';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Який атрибут <img> задає текстову альтернативу?',NULL,'["alt","src","title","loading"]'::jsonb,'[0]'::jsonb,'Правильна відповідь: alt. Варіант «alt» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «src» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «title» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «loading» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='accessibility';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Який атрибут <th> указує, чи є комірка заголовком рядка або стовпця?',NULL,'["scope","headers","colspan","rowspan"]'::jsonb,'[0]'::jsonb,'Правильна відповідь: scope. Варіант «scope» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «headers» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «colspan» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «rowspan» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='accessibility';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Який атрибут задає доступну назву через посилання на id іншого елемента?',NULL,'["aria-labelledby","aria-describedby","aria-hidden","aria-live"]'::jsonb,'[0]'::jsonb,'Правильна відповідь: aria-labelledby. Варіант «aria-labelledby» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «aria-describedby» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «aria-hidden» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «aria-live» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='accessibility';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які два твердження про alt інформативного зображення правильні?',NULL,'["Атрибут alt має передавати зміст або призначення зображення.","Порожнє значення alt використовують для декоративного зображення.","Атрибут alt має повторювати назву файлу зображення.","Атрибут alt задає фізичну ширину зображення.","Атрибут alt замінює адресу зображення у src."]'::jsonb,'[0,1]'::jsonb,'Правильні відповіді: Атрибут alt має передавати зміст або призначення зображення.; Порожнє значення alt використовують для декоративного зображення.. Варіант «Атрибут alt має передавати зміст або призначення зображення.» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «Порожнє значення alt використовують для декоративного зображення.» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «Атрибут alt має повторювати назву файлу зображення.» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Атрибут alt задає фізичну ширину зображення.» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Атрибут alt замінює адресу зображення у src.» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='accessibility';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які дві клавіші стандартно активують <button>, коли кнопка перебуває у фокусі?',NULL,'["Enter","Space","Tab","Escape","ArrowDown"]'::jsonb,'[0,1]'::jsonb,'Правильні відповіді: Enter; Space. Варіант «Enter» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «Space» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «Tab» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Escape» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «ArrowDown» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='accessibility';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які два елементи мають нативну клавіатурну взаємодію без додавання role?',NULL,'["<button>","<a href=\"/help\">","<div>","<span>","<section>"]'::jsonb,'[0,1]'::jsonb,'Правильні відповіді: <button>; <a href="/help">. Варіант «<button>» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «<a href="/help">» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «<div>» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «<span>» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «<section>» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='accessibility';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які два засоби пов’язують заголовкову комірку з даними таблиці?',NULL,'["<th>","scope","<td>","colspan","rowspan"]'::jsonb,'[0,1]'::jsonb,'Правильні відповіді: <th>; scope. Варіант «<th>» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «scope» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «<td>» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «colspan» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «rowspan» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='accessibility';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які два твердження про aria-labelledby правильні?',NULL,'["Значення aria-labelledby містить id елемента з текстом доступної назви.","Атрибут aria-labelledby може посилатися на видимий заголовок області.","Атрибут aria-labelledby змінює видимий текст заголовка.","Значення aria-labelledby містить URL-адресу документа.","Атрибут aria-labelledby приховує область від screen reader."]'::jsonb,'[0,1]'::jsonb,'Правильні відповіді: Значення aria-labelledby містить id елемента з текстом доступної назви.; Атрибут aria-labelledby може посилатися на видимий заголовок області.. Варіант «Значення aria-labelledby містить id елемента з текстом доступної назви.» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «Атрибут aria-labelledby може посилатися на видимий заголовок області.» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «Атрибут aria-labelledby змінює видимий текст заголовка.» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Значення aria-labelledby містить URL-адресу документа.» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Атрибут aria-labelledby приховує область від screen reader.» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='accessibility';
