INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Який елемент задає назву HTML-документа?',NULL,'["<title>","<h1>","<meta>","<header>"]'::jsonb,'[0]'::jsonb,'Правильна відповідь: <title>. Варіант «<title>» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «<h1>» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «<meta>» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «<header>» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='seo';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Який елемент позначає заголовок найвищого рівня у вмісті сторінки?',NULL,'["<h1>","<h2>","<title>","<header>"]'::jsonb,'[0]'::jsonb,'Правильна відповідь: <h1>. Варіант «<h1>» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «<h2>» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «<title>» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «<header>» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='seo';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Яке значення name у <meta> використовують для короткого опису сторінки?',NULL,'["description","robots","viewport","author"]'::jsonb,'[0]'::jsonb,'Правильна відповідь: description. Варіант «description» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «robots» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «viewport» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «author» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='seo';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Яке значення rel указує канонічну URL-адресу документа?',NULL,'["canonical","alternate","stylesheet","author"]'::jsonb,'[0]'::jsonb,'Правильна відповідь: canonical. Варіант «canonical» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «alternate» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «stylesheet» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «author» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='seo';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'easy','Який текст посилання найточніше описує перехід до розділу про HTML-форми?',NULL,'["Форми HTML","Натисніть тут","Докладніше","Перейти"]'::jsonb,'[0]'::jsonb,'Правильна відповідь: Форми HTML. Варіант «Форми HTML» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «Натисніть тут» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Докладніше» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Перейти» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='seo';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які два елементи задають назву документа та короткий метаопис?',NULL,'["<title>","<meta name=\"description\">","<h1>","<header>","<main>"]'::jsonb,'[0,1]'::jsonb,'Правильні відповіді: <title>; <meta name="description">. Варіант «<title>» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «<meta name="description">» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «<h1>» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «<header>» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «<main>» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='seo';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які два твердження про структуру HTML для пошуку правильні?',NULL,'["Заголовки передають ієрархію змісту сторінки.","Семантичні елементи описують призначення розділів.","Атрибут class безпосередньо визначає позицію сторінки у пошуку.","Елемент <div> має більшу семантичну вагу за <article>.","Порядок рівнів заголовків не впливає на структуру змісту."]'::jsonb,'[0,1]'::jsonb,'Правильні відповіді: Заголовки передають ієрархію змісту сторінки.; Семантичні елементи описують призначення розділів.. Варіант «Заголовки передають ієрархію змісту сторінки.» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «Семантичні елементи описують призначення розділів.» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «Атрибут class безпосередньо визначає позицію сторінки у пошуку.» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Елемент <div> має більшу семантичну вагу за <article>.» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Порядок рівнів заголовків не впливає на структуру змісту.» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='seo';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які два твердження про канонічну URL-адресу правильні?',NULL,'["Елемент <link> із rel=\"canonical\" указує основну URL-адресу документа.","Атрибут href у канонічному <link> містить цю URL-адресу.","Канонічний <link> змінює назву вкладки браузера.","Канонічний <link> забороняє індексування документа.","Значення rel=\"stylesheet\" указує канонічну URL-адресу."]'::jsonb,'[0,1]'::jsonb,'Правильні відповіді: Елемент <link> із rel="canonical" указує основну URL-адресу документа.; Атрибут href у канонічному <link> містить цю URL-адресу.. Варіант «Елемент <link> із rel="canonical" указує основну URL-адресу документа.» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «Атрибут href у канонічному <link> містить цю URL-адресу.» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «Канонічний <link> змінює назву вкладки браузера.» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Канонічний <link> забороняє індексування документа.» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Значення rel="stylesheet" указує канонічну URL-адресу.» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='seo';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які два твердження про alt інформативного зображення правильні?',NULL,'["Атрибут alt описує зміст або призначення зображення.","Текст alt може використовуватися, коли зображення недоступне.","Атрибут alt задає ширину зображення.","Атрибут alt замінює назву документа у <title>.","Атрибут alt указує канонічну URL-адресу сторінки."]'::jsonb,'[0,1]'::jsonb,'Правильні відповіді: Атрибут alt описує зміст або призначення зображення.; Текст alt може використовуватися, коли зображення недоступне.. Варіант «Атрибут alt описує зміст або призначення зображення.» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «Текст alt може використовуватися, коли зображення недоступне.» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «Атрибут alt задає ширину зображення.» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Атрибут alt замінює назву документа у <title>.» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «Атрибут alt указує канонічну URL-адресу сторінки.» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='seo';
INSERT INTO questions(topic_id,difficulty,prompt,code,options,correct_options,explanation) SELECT id,'medium','Які два Open Graph-метатеги задають заголовок і опис публікації?',NULL,'["<meta property=\"og:title\">","<meta property=\"og:description\">","<meta charset=\"UTF-8\">","<meta name=\"viewport\">","<meta name=\"robots\">"]'::jsonb,'[0,1]'::jsonb,'Правильні відповіді: <meta property="og:title">; <meta property="og:description">. Варіант «<meta property="og:title">» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «<meta property="og:description">» правильний: він відповідає умові та стандартній поведінці HTML. Варіант «<meta charset="UTF-8">» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «<meta name="viewport">» неправильний: він приписує елементу або атрибуту інше призначення. Варіант «<meta name="robots">» неправильний: він приписує елементу або атрибуту інше призначення. Правило: вибір потрібно робити за призначенням HTML-елементів і атрибутів або за точним результатом наведеного коду.' FROM topics WHERE slug='seo';
